const item = $input.item.json;

const posDishes = item.dishes || item.posDishes || [];
const weather = item.weather || {};
const events = item.events || item.nearbyEvents || [];

// Weather demand multiplier: cold/rainy conditions boost comfort-food demand, hot/sunny boosts cold-item demand
const tempF = weather.temperatureF ?? 70;
const condition = (weather.condition || '').toLowerCase();
const isRainy = condition.includes('rain') || condition.includes('storm');
const isCold = tempF < 50;
const isHot = tempF > 85;

// Event foot-traffic multiplier: sum of expected attendance nearby, scaled down to a reasonable multiplier
const totalNearbyAttendance = events.reduce((sum, e) => sum + (parseInt(e.expectedAttendance, 10) || 0), 0);
const eventFootTrafficMultiplier = 1 + Math.min(0.5, totalNearbyAttendance / 20000);

const dishFeatures = posDishes.map(d => {
  const dishName = d.name || d.dishName || 'Unknown Dish';
  const category = (d.category || '').toLowerCase();
  const ordersLast15Min = parseInt(d.ordersLast15Min, 10) || 0;
  const avgOrdersLast15Min = parseFloat(d.avgOrdersLast15Min) || 1;
  const velocityRatio = avgOrdersLast15Min > 0 ? Math.round((ordersLast15Min / avgOrdersLast15Min) * 100) / 100 : 1;

  let weatherMultiplier = 1;
  if ((isRainy || isCold) && category.includes('comfort')) weatherMultiplier = 1.15;
  if (isHot && (category.includes('cold') || category.includes('drink') || category.includes('dessert'))) weatherMultiplier = 1.15;

  return {
    dishName,
    category,
    currentPrice: parseFloat(d.currentPrice) || 0,
    ordersLast15Min, avgOrdersLast15Min, velocityRatio,
    weatherMultiplier,
    eventFootTrafficMultiplier: Math.round(eventFootTrafficMultiplier * 100) / 100,
    elasticityCoefficient: parseFloat(d.elasticityCoefficient) || 0.5
  };
});

return {
  json: {
    locationId: item.locationId || 'default-location',
    weatherCondition: weather.condition || 'Unknown',
    temperatureF: tempF,
    nearbyEventCount: events.length,
    totalNearbyAttendance,
    dishFeatures
  }
};

const item = $input.item.json;
const MAX_SURGE_PCT = 20;
const MAX_DISCOUNT_PCT = 10;

const pricingProposals = (item.dishFeatures || []).map(d => {
  // Combined demand signal: velocity vs baseline, weighted by weather and event multipliers
  const combinedDemandSignal = d.velocityRatio * d.weatherMultiplier * d.eventFootTrafficMultiplier;

  // Elasticity-adjusted price delta: how much demand deviates from 1.0 (normal), scaled by the dish's elasticity coefficient
  const demandDeviation = combinedDemandSignal - 1;
  let pctChange = Math.round(demandDeviation * d.elasticityCoefficient * 100 * 10) / 10;

  // Cap surge and discount bands
  if (pctChange > MAX_SURGE_PCT) pctChange = MAX_SURGE_PCT;
  if (pctChange < -MAX_DISCOUNT_PCT) pctChange = -MAX_DISCOUNT_PCT;

  const proposedPrice = Math.round(d.currentPrice * (1 + pctChange / 100) * 100) / 100;

  return {
    dishName: d.dishName,
    category: d.category,
    currentPrice: d.currentPrice,
    combinedDemandSignal: Math.round(combinedDemandSignal * 100) / 100,
    proposedPctChange: pctChange,
    proposedPrice
  };
});

return {
  json: {
    ...item,
    pricingProposals
  }
};

