const item = $input.item.json;
let parsed = {};
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  // Fallback: keep every price unchanged if AI parsing fails
  parsed = {
    decisions: (item.pricingProposals || []).map(p => ({
      dishName: p.dishName,
      decision: 'Rejected',
      finalPrice: p.currentPrice,
      reasoning: 'AI review unavailable this cycle; price held at current value as a safety default.'
    })),
    overallRiskNote: 'AI brand-damage check could not be parsed this cycle; all prices held unchanged.'
  };
}

const decisionsByDish = {};
for (const d of (parsed.decisions || [])) {
  decisionsByDish[d.dishName] = d;
}

const finalPrices = (item.pricingProposals || []).map(p => {
  const d = decisionsByDish[p.dishName];
  return {
    dishName: p.dishName,
    currentPrice: p.currentPrice,
    proposedPrice: p.proposedPrice,
    decision: d ? d.decision : 'Rejected',
    finalPrice: d ? d.finalPrice : p.currentPrice,
    reasoning: d ? d.reasoning : 'No decision returned; price held at current value.'
  };
});

return {
  json: {
    locationId: item.locationId,
    cycleTimestamp: new Date().toISOString(),
    overallRiskNote: parsed.overallRiskNote || '',
    finalPrices
  }
};
